// =============================================================================
// KS-1204 — a connector allow-list that is not an array fails closed, and
//           documentType wins over type (#1014 gate N-2 + N-3)
// =============================================================================
//
// POST /api/documents under a connector key checks the connector's
// allowedDocumentTypes, read from platform-settings integrations. That value is
// stored by PUT /api/admin/settings, which merges the body verbatim, so it is not
// guaranteed to be an array. The route cast it to string[] and called
// `.includes`: for a STRING that is a substring match, so a connector restricted
// to "SSD_DOCUMENT" could create DOCUMENT ("SSD_DOCUMENT".includes("DOCUMENT")).
// An object threw.
//
// Now a configured allow-list that is not an array refuses every create, 403
// FORBIDDEN, before enforcement (fail closed). An absent or null allow-list still
// means no restriction, and an empty array too (`length > 0`), exactly as before.
//
// N-3: the route and enforcement resolve `documentType || type`. No cell pinned
// that precedence, so a tamper reversing it stayed green. The two precedence
// cells send both keys disagreeing, in both directions.
//
// Harness: the ks1176 pattern (the real verification router and the real
// enforceDocumentTypeRules over the seeded catalogue; the workflow gate is a spy
// that answers 201 "past-enforcement").
// =============================================================================

import { describe, it, expect, beforeAll, afterAll, afterEach, vi } from 'vitest';
import express from 'express';
import http from 'node:http';
import type { Server } from 'node:http';
import type { AddressInfo } from 'node:net';
import type { RequestHandler } from 'express';

const catalogue = vi.hoisted(() => ({ types: [] as Array<Record<string, unknown>> }));

// enforceDocumentTypeRules resolves document types through this module directly.
vi.mock('../services/redis', () => ({
  getAllDocumentTypes: vi.fn(async () => catalogue.types),
}));

import { meetsVerificationLevel, enforceDocumentTypeRules } from '../services/enforcement';
import { SEED_DOCUMENT_TYPES } from '../routes/admin';

const DOC_ID = 'doc-ks1204';
const CONTENT_HASH = 'c'.repeat(64);

/** The principal authenticateToken builds for an sk_ key (middleware/auth.ts). */
const CONNECTOR = {
  userId: 'connector:ks1204-c1',
  email: 'connector@secuura.io',
  role: 'connector',
  organizationId: 'org-1',
  verificationLevel: 'api_key',
  authMethod: 'api_key',
  connectorId: 'ks1204-c1',
  rateLimit: 100,
  rateLimitWindow: 60,
  scopes: ['documents:write'],
  tenantId: 't1',
};
const CONNECTOR_META = {
  connectorId: 'ks1204-c1',
  scopes: ['documents:write'],
  organizationId: 'org-1',
  tenantId: 't1',
  rateLimit: 100,
  rateLimitWindow: 60,
};

const SSD_DOCUMENT = SEED_DOCUMENT_TYPES.find((dt) => (dt as { code?: string }).code === 'SSD_DOCUMENT') as
  | Record<string, unknown>
  | undefined;
const STANDARD_TYPE = {
  id: 'dt-ks1204-standard',
  name: 'KS1204 standard',
  code: 'KS1204_STANDARD',
  isActive: true,
  creatorVerificationLevel: 'standard',
  verifierVerificationLevel: 'standard',
  requireMFA: false,
  allowedAuthProviders: [],
  metadataSchema: [],
};
const DOCUMENT_TYPE = SEED_DOCUMENT_TYPES.find((dt) => (dt as { code?: string }).code === 'DOCUMENT') as
  | Record<string, unknown>
  | undefined;
/** The connector's stored allowedDocumentTypes for the current cell. ABSENT = the key is not in the config at all. */
const ABSENT = Symbol('absent');
let connectorAllowedTypes: unknown = ABSENT;
const OPEN_VERIFY_TYPE = {
  id: 'dt-ks1204-open',
  name: 'KS1204 open',
  code: 'KS1204_OPEN',
  isActive: true,
  creatorVerificationLevel: 'none',
  verifierVerificationLevel: 'none',
  requireMFA: false,
  allowedAuthProviders: [],
  metadataSchema: [],
};

let principal: Record<string, unknown> = CONNECTOR;
/** documentType the stub originate reports for DOC_ID. */
const storedDocType = STANDARD_TYPE.code;

const enforceSpy = vi.fn(enforceDocumentTypeRules);
const workflowSpy = vi.fn(async () => ({ gated: true as const, response: { success: true, data: { ks1204: 'past-enforcement' } } }));

let gateway: Server;
let originate: Server;
let gatewayPort: number;
const realFetch = globalThis.fetch;
const jsonHead = { 'Content-Type': 'application/json' };

beforeAll(async () => {
  catalogue.types = [SSD_DOCUMENT as Record<string, unknown>, DOCUMENT_TYPE as Record<string, unknown>, STANDARD_TYPE, OPEN_VERIFY_TYPE];

  // Stub originate: serves DOC_ID for the verify route's first lookup tier.
  originate = http.createServer((req, res) => {
    if (req.url === `/api/documents/${DOC_ID}`) {
      res.writeHead(200, jsonHead);
      res.end(JSON.stringify({
        id: DOC_ID,
        status: 'anchored',
        contentHash: CONTENT_HASH,
        documentType: storedDocType,
        owner: { id: 'org-1' },
      }));
      return;
    }
    res.writeHead(404, jsonHead);
    res.end('{}');
  });
  originate.listen(0, '127.0.0.1');
  await new Promise<void>((r) => originate.once('listening', () => r()));
  const originatePort = (originate.address() as AddressInfo).port;

  // The verify route's chain scan answers "no live hit".
  globalThis.fetch = (async () => ({ ok: false, status: 404, json: async () => ({}), text: async () => '' })) as never;

  const { createVerificationRoutes } = await import('../routes/verification');
  const mockBodyParser: RequestHandler = express.json({ limit: '1mb' });

  const app = express();
  app.use(
    createVerificationRoutes({
      authenticateToken: () => (req, _res, next) => {
        (req as { user?: unknown }).user = { ...principal };
        if (principal.authMethod === 'api_key') (req as { connectorMeta?: unknown }).connectorMeta = { ...CONNECTOR_META };
        next();
      },
      mockBodyParser,
      query: vi.fn(async () => ({ rows: [] })) as never,
      isDbAvailable: () => false,
      redisService: {
        getPendingDocument: vi.fn(async () => null),
        deletePendingDocument: vi.fn(async () => undefined),
        getAllDocumentTypes: vi.fn(async () => catalogue.types),
        getAllWorkflowInstances: vi.fn(async () => []),
        // KS-1204: the route reads the connector's allow-list from platform-settings integrations.
        // The route reads the connector's allow-list from platform-settings integrations, stored as the admin write left it.
        getNotificationSettings: vi.fn(async () => ({
          integrations: [{ id: CONNECTOR_META.connectorId, config: connectorAllowedTypes === ABSENT ? {} : { allowedDocumentTypes: connectorAllowedTypes } }],
        })),
        getRejectedDocument: vi.fn(async () => null),
        setRejectedDocument: vi.fn(async () => undefined),
        getWorkflowDocumentMapping: vi.fn(async () => null),
        getWorkflowInstance: vi.fn(async () => null),
        setWorkflowInstance: vi.fn(async () => undefined),
      } as never,
      services: {
        originate: { url: `http://127.0.0.1:${originatePort}` },
        anchoring: { url: `http://127.0.0.1:${originatePort}` },
      } as never,
      log: () => undefined,
      memWorkflowToDocumentMap: new Map(),
      memRejectedDocuments: new Map(),
      dbSaveRejection: vi.fn(async () => undefined),
      ADMIN_ROLES: ['ADMIN', 'admin'],
      // The real helpers: these cells are about what they decide.
      enforceDocumentTypeRules: enforceSpy as never,
      createWorkflowInstanceIfRequired: workflowSpy as never,
      meetsVerificationLevel,
    }),
  );

  gateway = app.listen(0, '127.0.0.1');
  await new Promise<void>((r) => gateway.once('listening', () => r()));
  gatewayPort = (gateway.address() as AddressInfo).port;
});

afterAll(async () => {
  globalThis.fetch = realFetch;
  await new Promise<void>((r) => gateway.close(() => r()));
  await new Promise<void>((r) => originate.close(() => r()));
});

/** KS-1204: POST /api/documents with a caller-shaped body (`type`, `documentType`, or neither). */
async function createDocumentWithBody(as: Record<string, unknown>, body: Record<string, unknown>): Promise<{ status: number; body: any }> {
  principal = as;
  enforceSpy.mockClear();
  workflowSpy.mockClear();
  const r = await realFetch(`http://127.0.0.1:${gatewayPort}/api/documents`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: 'Bearer t' },
    body: JSON.stringify({ title: 'KS-1204', contentHash: CONTENT_HASH, ...body }),
  });
  return { status: r.status, body: await r.json() };
}


const RAN = new Set<string>();

describe('KS-1204 N-2 — a configured allow-list that is not an array refuses every create (fail closed)', () => {
  afterEach(() => {
    connectorAllowedTypes = ABSENT;
  });

  const NON_ARRAYS: Array<[string, unknown]> = [
    ['the string "SSD_DOCUMENT"', 'SSD_DOCUMENT'],
    ['an object', { 0: 'SSD_DOCUMENT' }],
    ['an empty string', ''],
  ];

  it('🔴 a string allow-list "SSD_DOCUMENT" no longer substring-matches DOCUMENT: 403 FORBIDDEN, enforcement never runs', async () => {
    RAN.add('string vs DOCUMENT');
    connectorAllowedTypes = 'SSD_DOCUMENT';
    const { status, body } = await createDocumentWithBody(CONNECTOR, { documentType: 'DOCUMENT' });
    expect([status, body?.error?.code, enforceSpy.mock.calls.length, workflowSpy.mock.calls.length]).toEqual([403, 'FORBIDDEN', 0, 0]);
  });

  for (const [label, value] of NON_ARRAYS) {
    it(`🔴 ${label} as the allow-list refuses even the type it names, and an untyped body: 403 FORBIDDEN both, enforcement never runs`, async () => {
      RAN.add(`non-array ${label}`);
      connectorAllowedTypes = value;
      const named = await createDocumentWithBody(CONNECTOR, { documentType: 'SSD_DOCUMENT' });
      const untyped = await createDocumentWithBody(CONNECTOR, {});
      expect([named.status, named.body?.error?.code, untyped.status, untyped.body?.error?.code, enforceSpy.mock.calls.length, workflowSpy.mock.calls.length])
        .toEqual([403, 'FORBIDDEN', 403, 'FORBIDDEN', 0, 0]);
    });
  }

  it('control: an ARRAY allow-list ["SSD_DOCUMENT"] admits SSD_DOCUMENT and refuses DOCUMENT, as before', async () => {
    RAN.add('array control');
    connectorAllowedTypes = ['SSD_DOCUMENT'];
    const allowed = await createDocumentWithBody(CONNECTOR, { documentType: 'SSD_DOCUMENT' });
    expect([allowed.status, allowed.body?.data?.ks1204]).toEqual([201, 'past-enforcement']);
    const refused = await createDocumentWithBody(CONNECTOR, { documentType: 'DOCUMENT' });
    expect([refused.status, refused.body?.error?.code]).toEqual([403, 'FORBIDDEN']);
  });

  it('control: an absent, null or empty-array allow-list is no restriction, as before', async () => {
    RAN.add('unrestricted control');
    const statuses: unknown[] = [];
    for (const value of [ABSENT, null, []]) {
      connectorAllowedTypes = value;
      const r = await createDocumentWithBody(CONNECTOR, { documentType: 'DOCUMENT' });
      statuses.push([r.status, r.body?.data?.ks1204]);
    }
    expect(statuses).toEqual([[201, 'past-enforcement'], [201, 'past-enforcement'], [201, 'past-enforcement']]);
  });
});

describe('KS-1204 N-3 — documentType wins over type when both are sent', () => {
  afterEach(() => {
    connectorAllowedTypes = ABSENT;
  });

  it('allow-list ["SSD_DOCUMENT"], documentType SSD_DOCUMENT + type DOCUMENT: 201, and enforcement resolves SSD_DOCUMENT', async () => {
    RAN.add('precedence admits documentType');
    connectorAllowedTypes = ['SSD_DOCUMENT'];
    const { status, body } = await createDocumentWithBody(CONNECTOR, { documentType: 'SSD_DOCUMENT', type: 'DOCUMENT' });
    const resolved = enforceSpy.mock.results.length ? ((await enforceSpy.mock.results[0].value) as { docType?: { code?: string } }).docType?.code : null;
    expect([status, body?.data?.ks1204, resolved]).toEqual([201, 'past-enforcement', 'SSD_DOCUMENT']);
  });

  it('allow-list ["SSD_DOCUMENT"], documentType DOCUMENT + type SSD_DOCUMENT: 403 FORBIDDEN naming "DOCUMENT"', async () => {
    RAN.add('precedence refuses documentType');
    connectorAllowedTypes = ['SSD_DOCUMENT'];
    const { status, body } = await createDocumentWithBody(CONNECTOR, { documentType: 'DOCUMENT', type: 'SSD_DOCUMENT' });
    expect([status, body?.error?.code, body?.error?.message, enforceSpy.mock.calls.length]).toEqual([403, 'FORBIDDEN', 'Connector is not permitted to register document type "DOCUMENT"', 0]);
  });
});

describe('KS-1204 COMPLETENESS', () => {
  it('every graded cell above actually ran', () => {
    expect([...RAN].sort()).toEqual([
      'string vs DOCUMENT', 'non-array the string "SSD_DOCUMENT"', 'non-array an object', 'non-array an empty string',
      'array control', 'unrestricted control', 'precedence admits documentType', 'precedence refuses documentType',
    ].sort());
  });
});
